1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Emits the create audit trail. Runs after the owner is saved (so its id is
10	 * assigned) and before the response is sent, writing a single line to the
11	 * dedicated {@code AUDIT} logger carrying the new owner's id, customer code,
12	 * registration date, derived membership level and membership number.
13	 */
14	public class AuditOwnerCreated {
15	
16	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
17	
18	    public void service(@Val Owner owner) {
19	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
20	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
21	                MembershipLevel.of(owner), membershipNumber(owner));
22	    }
23	
24	    private static String membershipNumber(Owner owner) {
25	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
26	            return null;
27	        }
28	        return owner.getCustomerCode() + "-M"
29	                + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
30	    }
31	}
