1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The owner's customer code — the single derived identity every other value hangs off. It is
7	 * {@code '<REGION>-<HASH8>'}: REGION is the canonical region derived from the owner's postcode
8	 * (falling back to the city table via {@link Locality}); HASH8 is the first 8 UPPER-case hex
9	 * characters of SHA-256 over the normalized (E.164) telephone concatenated with the last name.
10	 *
11	 * <p>There are no sequence numbers: the code is a pure function of region, telephone and last
12	 * name, so it needs no repository scan and is stable for a given owner. The membership number,
13	 * its Luhn check digit ({@link CheckDigit}), the create audit line and the reported locality
14	 * ({@link #region(String)}) are all built from this one value.
15	 */
16	public final class CustomerCode {
17	
18	    private CustomerCode() {
19	    }
20	
21	    /** The {@code '<REGION>-<HASH8>'} customer code for {@code owner}. */
22	    public static String of(Owner owner) {
23	        String region = Locality.of(owner.getCity(), owner.getPostcode());
24	        String hash8 = ShaHex.upperPrefix(owner.getTelephone() + owner.getLastName(), 8);
25	        return region + "-" + hash8;
26	    }
27	
28	    /**
29	     * De-duplicate a computed customer code against those already in use. When {@code code}
30	     * collides with an existing owner's customer code, the smallest {@code n} of 2 or more is
31	     * appended as {@code '-<n>'} to make it unique; a code that does not collide is returned
32	     * unchanged (as is a {@code null} code).
33	     *
34	     * @param code          the computed customer code to make unique
35	     * @param existingCodes the customer codes already assigned to other owners
36	     * @return the de-duplicated customer code
37	     */
38	    public static String dedupe(String code, java.util.Set<String> existingCodes) {
39	        if (code == null || !existingCodes.contains(code)) {
40	            return code;
41	        }
42	        for (int n = 2; ; n++) {
43	            String candidate = code + "-" + n;
44	            if (!existingCodes.contains(candidate)) {
45	                return candidate;
46	            }
47	        }
48	    }
49	
50	    /**
51	     * The REGION component of a customer code (everything before the final {@code '-'}), or
52	     * {@code null} when the code is absent. This is the owner's locality, now read straight off
53	     * the identity rather than re-derived.
54	     */
55	    public static String region(String customerCode) {
56	        if (customerCode == null) {
57	            return null;
58	        }
59	        int hyphen = customerCode.lastIndexOf('-');
60	        return hyphen < 0 ? customerCode : customerCode.substring(0, hyphen);
61	    }
62	}
