1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's membership points and the numeric membership level mapped from them.
9	 * Points start at 0 and gain: 2 when an email is present, 1 when {@code namesakeCount} is 0,
10	 * 2 for a household of 3 or more members, and 3 for tenure of more than one elapsed fiscal
11	 * year (measured from {@code registrationDate}). Points map to a level (1 to 4): 1 for 0-1
12	 * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
13	 */
14	public final class MembershipLevel {
15	
16	    /** Points awarded when an email is present. */
17	    private static final int EMAIL_POINTS = 2;
18	
19	    /** Points awarded when the owner has no namesakes. */
20	    private static final int NO_NAMESAKE_POINTS = 1;
21	
22	    /** Points awarded for a household of {@link #HOUSEHOLD_THRESHOLD} or more members. */
23	    private static final int HOUSEHOLD_POINTS = 2;
24	
25	    /** Household size at or above which household points are awarded. */
26	    private static final int HOUSEHOLD_THRESHOLD = 3;
27	
28	    /** Points awarded when tenure exceeds {@link #TENURE_FISCAL_YEARS} elapsed fiscal years. */
29	    private static final int TENURE_POINTS = 3;
30	
31	    /** Elapsed fiscal years beyond which an owner earns tenure points. */
32	    private static final long TENURE_FISCAL_YEARS = 1;
33	
34	    private MembershipLevel() {
35	    }
36	
37	    /** Membership points derived from the owner's email, namesake count, household size and tenure. */
38	    public static int points(Owner owner) {
39	        int points = 0;
40	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
41	            points += EMAIL_POINTS;
42	        }
43	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
44	            points += NO_NAMESAKE_POINTS;
45	        }
46	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
47	            points += HOUSEHOLD_POINTS;
48	        }
49	        if (elapsedFiscalYears(owner) > TENURE_FISCAL_YEARS) {
50	            points += TENURE_POINTS;
51	        }
52	        return points;
53	    }
54	
55	    /** Membership level (1 to 4) mapped from the owner's {@link #points(Owner) membership points}. */
56	    public static int of(Owner owner) {
57	        int points = points(owner);
58	        if (points >= 6) {
59	            return 4;
60	        }
61	        if (points >= 4) {
62	            return 3;
63	        }
64	        if (points >= 2) {
65	            return 2;
66	        }
67	        return 1;
68	    }
69	
70	    /** Fiscal years elapsed since the owner's registrationDate; 0 when the date is absent or in the future. */
71	    private static long elapsedFiscalYears(Owner owner) {
72	        LocalDate registrationDate = owner.getRegistrationDate();
73	        if (registrationDate == null) {
74	            return 0;
75	        }
76	        long years = FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate);
77	        return Math.max(years, 0);
78	    }
79	}
