1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Makes the computed {@link CustomerCode customer code} unique before the owner is saved. The code
12	 * is a pure function of region, telephone and last name, so two distinct owners can in principle
13	 * derive the same value; when the code collides with an existing owner's customer code, the
14	 * smallest {@code n} of 2 or more is appended as {@code '-<n>'} (see
15	 * {@link CustomerCode#dedupe(String, Set)}). Runs after the code has been stamped by
16	 * {@link BuildOwner} and before {@link SaveOwner}, mutating the owner in place.
17	 */
18	public class DeduplicateCustomerCode {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Set<String> existing = new HashSet<>();
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (other.getId() != null && other.getId().equals(owner.getId())) {
24	                continue; // same record, not a collision
25	            }
26	            if (other.getCustomerCode() != null) {
27	                existing.add(other.getCustomerCode());
28	            }
29	        }
30	        owner.setCustomerCode(CustomerCode.dedupe(owner.getCustomerCode(), existing));
31	    }
32	}
33

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Caps the new owner's membership level. A new owner's {@link MembershipLevel level} may not
9	 * exceed one above the CURRENT maximum level among the existing members of their household —
10	 * owners sharing the same {@link Household#id(Owner) householdId}, matched the same way as
11	 * {@link AssignOwnerHousehold}. The uncapped level is {@link MembershipLevel#of(Owner)}; the
12	 * capped result is stamped on the owner via {@link Owner#setMembershipLevel(Integer)} and later
13	 * returned as {@code membershipLevel}. With no existing household member no cap applies.
14	 *
15	 * <p>An existing member's level is its stored (already-capped) value when present, else the
16	 * derived {@link MembershipLevel#of(Owner)}. Runs after {@link AssignOwnerHousehold} and
17	 * {@link CountOwnerNamesakes} (so household id, size and namesake count are stamped) and before
18	 * {@link SaveOwner}.
19	 */
20	public class CapOwnerMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        int level = MembershipLevel.of(owner);
24	        String householdId = owner.getHouseholdId();
25	        Integer maxExisting = null;
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
28	                continue; // an owner is not its own household member
29	            }
30	            if (householdId != null && householdId.equals(Household.id(existing))) {
31	                int existingLevel = existing.getMembershipLevel() != null
32	                        ? existing.getMembershipLevel()
33	                        : MembershipLevel.of(existing);
34	                if (maxExisting == null || existingLevel > maxExisting) {
35	                    maxExisting = existingLevel;
36	                }
37	            }
38	        }
39	        if (maxExisting != null && level > maxExisting + 1) {
40	            level = maxExisting + 1; // cap at one above the current household maximum
41	        }
42	        owner.setMembershipLevel(level);
43	    }
44	}
