1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helpers. The fiscal year starts on 1 July and is named for the
7	 * calendar year in which it ends: a date on or after 1 July belongs to the next
8	 * calendar year's fiscal year (e.g. 2025-07-01 -> FY26), a date before 1 July to
9	 * the current calendar year's (e.g. 2026-06-30 -> FY26).
10	 */
11	public final class FiscalYear {
12	
13	    /** First month of the fiscal year (July). */
14	    private static final int FISCAL_START_MONTH = 7;
15	
16	    private FiscalYear() {
17	    }
18	
19	    /** The full four-digit fiscal year that {@code date} falls in. */
20	    public static int of(LocalDate date) {
21	        return date.getMonthValue() >= FISCAL_START_MONTH ? date.getYear() + 1 : date.getYear();
22	    }
23	
24	    /** The fiscal-year label 'FY<YY>' (two-digit) for {@code date}. */
25	    public static String label(LocalDate date) {
26	        return String.format("FY%02d", of(date) % 100);
27	    }
28	}
